propuesta.texto_viejo:
if trozos and archivo:
    solo = []
    i = 0
    t = bloques[trozos]
    while i < len(t):
        if t[i].startswith("### `"):
            j = i + 1
            while j < len(t) and not t[j].startswith("### `"):
                j += 1
            if archivo in t[i]:
                solo += t[i:j]
            i = j
        else:
            solo.append(t[i])
            i += 1
    if solo:
        salida += solo
elif trozos:
    # Sin archivo a que atarse, quedan los bloques de trozos, del mas relevante para abajo
    # hasta que entre en el tope. El relleno de menor relevancia se suelta primero.
    t = bloques[trozos]
    bloques_trozo = []
    i = 0
    while i < len(t):
        if t[i].startswith("### `"):
            j = i + 1
            while j < len(t) and not t[j].startswith("### `"):
                j += 1
            m = re.search(r"relevancia\s+([\d\.]+)", t[i])
            bloques_trozo.append((float(m.group(1)) if m else 0.0, t[i:j]))
            i = j
        else:
            i += 1
    bloques_trozo.sort(key=lambda x: x[0], reverse=True)
    resto = salida
    for _relev, _lines in bloques_trozo:
        if len("\n".join(resto)) >= tope:
            break
        resto = resto + _lines
    salida = resto
# Si aun asi se pasa del tope, se va soltando el relleno del final hasta caber: la cabecera,
# la ley y "a quien puede danar" son LO NECESARIO, no se tocan.
while len("\n".join(salida)) > tope and len(salida) > len(bloques["__cabecera__"]):
    salida.pop()
return "\n".join(salida)

propuesta.texto_nuevo:
if trozos:
    t = bloques[trozos]
    # Se separan los bloques de trozos (### `ruta`) del texto suelto que los precede.
    # El texto suelto NUNCA se tira: es parte del material y puede contener la ley o el encargo.
    bloques_trozo = []
    sueltos = []
    i = 0
    while i < len(t):
        if t[i].startswith("### `"):
            j = i + 1
            while j < len(t) and not t[j].startswith("### `"):
                j += 1
            m = re.search(r"relevancia\s+([\d\.]+)", t[i])
            bloques_trozo.append((float(m.group(1)) if m else 0.0, t[i:j]))
            i = j
        else:
            sueltos.append(t[i])
            i += 1
    # Si se pide un archivo concreto, se conservan TODOS los bloques cuyo encabezado
    # mencione ese archivo (coincidencia por ruta o por nombre de archivo), y ademas
    # los sueltos. Si no hay coincidencia, se conservan los sueltos y los bloques de
    # mayor relevancia hasta el tope, sin borrar nunca los sueltos.
    if archivo:
        nombre = archivo.replace("\\", "/").split("/")[-1]
        elegidos = [b for b in bloques_trozo if archivo in b[1][0] or nombre in b[1][0]]
        if elegidos:
            salida += sueltos
            for _relev, _lines in elegidos:
                salida += _lines
        else:
            salida += sueltos
            bloques_trozo.sort(key=lambda x: x[0], reverse=True)
            for _relev, _lines in bloques_trozo:
                if len("\n".join(salida)) >= tope:
                    break
                salida += _lines
    else:
        # Sin archivo a que atarse, se conservan los sueltos y se anaden bloques por
        # relevancia hasta el tope. El relleno de menor relevancia se suelta primero.
        salida += sueltos
        bloques_trozo.sort(key=lambda x: x[0], reverse=True)
        for _relev, _lines in bloques_trozo:
            if len("\n".join(salida)) >= tope:
                break
            salida += _lines
# Si aun asi se pasa del tope, se va soltando el relleno del final hasta caber: la cabecera,
# la ley y "a quien puede danar" son LO NECESARIO, no se tocan.
while len("\n".join(salida)) > tope and len(salida) > len(bloques["__cabecera__"]):
    salida.pop()
return "\n".join(salida)

